<script>
  import { cardTable } from "$lib/ui/cardTable.js";
  import Flow from "$lib/ui/Flow.svelte";
  import { live } from "$lib/live.js";
  import { onMount } from "svelte";
  import { api } from "$lib/api.js";
  import { t } from "$lib/i18n/index.svelte.js";
  let st = $state(null), problem = $state(null), domain = $state(""), pw = $state(""), to = $state(""), note = $state(null), busy = $state(false);
  const domainSteps = $derived((() => { const ok = st?.domain?.status === "verified"; const has = Boolean(st?.domain); return [{ title: t("Add your domain"), line: t("yourcompany.com"), icon: "globe", state: has ? "done" : "current" }, { title: t("Add the records"), line: t("At your DNS host"), icon: "server", state: ok ? "done" : has ? "current" : "todo" }, { title: t("We check them"), line: t("Check now"), icon: "refresh", state: ok ? "done" : "todo" }, { title: t("Verified"), line: t("Signers see your name"), icon: "badge-check", state: ok ? "done" : "todo" }]; })());
  const load = async () => { const r = await api("/api/documents/email"); if (r.ok) st = r.json; else problem = r.error ?? t("Email settings could not be loaded."); };
  const flag = typeof location !== "undefined" ? new URLSearchParams(location.search).get("mailbox") : null;
  const FLAGS = $derived({ connected: t("Your mailbox is connected. Emails now go out from it."), declined: t("The connection was cancelled. Nothing changed."), expired: t("That connection attempt expired. Start again."), failed: t("The connection did not complete. Start again, or tell us if it keeps happening.") });
  onMount(() => { const stop = live(["email", "settings"], load); return stop; });
  onMount(async () => { await load(); if (flag && FLAGS[flag]) note = FLAGS[flag]; if (flag) history.replaceState(null, "", "?tab=email"); });
  async function connect(provider) { busy = true; note = null; const r = await api("/api/documents/email/mailbox/connect", { method: "POST", body: { provider } }); busy = false; if (r.ok && r.json?.url) location.href = r.json.url; else note = r.error ?? t("Connecting did not start."); }
  async function go(path, body, ok) { busy = true; note = null; const r = await api(path, { method: "POST", body }); busy = false; note = r.ok ? ok : (r.error ?? t("That did not work.")); if (r.ok) await load(); }
</script>
{#if problem}<p class="text-bad" role="alert">{problem}</p>{:else if !st}<p class="text-mute" style="min-height: 57rem">{t("Loading…")}</p>{:else}
<div class="max-w-3xl space-y-6">
  <section class="rounded-xl border border-line p-5"><h2 class="font-semibold">{t("Who your emails come from")}</h2>
    {#if st.state === "not_configured"}<p class="mt-2 rounded-lg border border-warn-line bg-warn-bg px-3 py-2 text-[15px]" role="alert" data-testid="email-not-set-up"><strong>{t("Email isn't set up yet.")}</strong> {t("Nothing can be emailed to signers until you choose how mail goes out below: your own mail server, your own domain or a connected mailbox. Then send yourself a test.")}</p>
    {:else}<p class="mt-2 text-[15px]">{st.mode === "platform" ? t("Right now signers see “{name} via {platform}” from {address}. Replies go to you.", { name: st.from?.name ?? t("your organisation"), platform: st.from?.platform?.name ?? "Docustay", address: st.from?.platform?.address ?? t("our address") }) : t("{mode, select, smtp {Emails go out from {address} through your own mail server.} mailbox {Emails go out from {address} through your {provider} mailbox.} other {Emails go out from {address} through your own domain.}}", { mode: st.mode, address: st.from?.address ?? t("your own address"), provider: st.mailbox?.providerLabel ?? "" })}</p>{/if}
    {#if st.fallbackReason || st.fallback?.now}<p class="mt-3 rounded-lg border border-warn-line bg-warn-bg px-3 py-2 text-sm" role="alert" data-testid="email-fallback-now"><strong>{t("Emails are NOT going out from the sender you chose.")}</strong> {st.fallbackReason ?? st.fallback?.reason}</p>{/if}
    {#if st.fallback?.count}<p class="mt-2 text-sm text-mute" data-testid="email-fallback-count">{t("{n, plural, one {# email went from the platform address instead of your chosen sender — the latest on {date}: {reason}} other {# emails went from the platform address instead of your chosen sender — the latest on {date}: {reason}}}", { n: st.fallback.count, date: new Date(st.fallback.at).toLocaleString(), reason: st.fallback.reason })}</p>{/if}
    {#if st.limit}<p class="mt-1 text-sm text-mute">{st.limit.limit ? t("{sent} of {limit} emails sent today.", { sent: st.limit.sent, limit: st.limit.limit }) : t("{sent} emails sent today. This install has no daily limit.", { sent: st.limit.sent })}</p>{/if}</section>
  <section class="rounded-xl border border-line p-5" data-testid="email-mailbox"><h2 class="font-semibold">{t("Send from your own mailbox")}</h2><p class="mt-1 text-sm text-mute">{t("Connect your Google or Microsoft account. Emails go out as you, appear in your Sent folder, and replies come to your inbox. We can only send; we cannot read your mail.")}</p>
    {#if st.mailbox}<p class="mt-3 text-sm" data-testid="email-mailbox-connected">{t("Connected as {email} ({provider})", { email: st.mailbox.email, provider: st.mailbox.providerLabel })}{#if st.mailbox.status !== "connected"} — <span class="text-bad">{t("needs to be connected again")}{st.mailbox.lastError ? `: ${st.mailbox.lastError}` : ""}</span>{/if}{#if st.mailbox.lastUsedAt} · {t("last used {date}", { date: new Date(st.mailbox.lastUsedAt).toLocaleString() })}{/if}</p>
      <div class="mt-3 flex flex-wrap gap-2">{#if st.mailbox.status !== "connected"}<button class="btn primary" disabled={busy} onclick={() => connect(st.mailbox.provider)}>{t("Connect again")}</button>{/if}<button class="btn" disabled={busy} onclick={() => go("/api/documents/email/mailbox/disconnect", {}, t("Disconnected. Emails go out from the platform address."))}>{t("Disconnect")}</button></div>
    {:else}<div class="mt-3 flex flex-wrap gap-2">{#each st.mailboxProviders ?? [] as p}<button class="btn" disabled={busy || !p.available} onclick={() => connect(p.key)} title={p.available ? "" : t("Not set up on this server yet")} data-testid={`email-connect-${p.key}`}>{t("Connect {provider}", { provider: p.label })}</button>{/each}</div>{#if (st.mailboxProviders ?? []).some((p) => !p.available)}<p class="mt-2 text-xs text-mute">{t("A provider that is greyed out is not set up on this server yet.")}</p>{/if}{/if}</section>
  <section class="rounded-xl border border-line p-5"><h2 class="font-semibold">{t("Send from your own domain")}</h2><div class="mt-3"><Flow steps={domainSteps} /></div><p class="mt-1 text-sm text-mute">{t("Signers then see a name they know. You add a few records at your domain's DNS host; we check them.")}</p>
    {#if st.domain}<p class="mt-3 text-sm"><strong>{st.domain.domain}</strong> — {st.domain.status}{#if st.domain.lastError}<span class="text-bad"> · {st.domain.lastError}</span>{/if}</p>
      <div class="mt-3 overflow-x-auto"><table use:cardTable class="card-table w-full min-w-[480px] text-left text-sm"><thead class="text-xs uppercase text-mute"><tr><th class="py-1 pr-3">{t("Type")}</th><th class="py-1 pr-3">{t("Name")}</th><th class="py-1 pr-3">{t("Value")}</th><th class="py-1">{t("Status")}</th></tr></thead><tbody>{#each st.domain.records ?? [] as r}<tr class="border-t border-line"><td class="py-1.5 pr-3">{r.type}</td><td class="py-1.5 pr-3 font-mono text-xs">{r.name}</td><td class="max-w-[260px] break-all py-1.5 pr-3 font-mono text-xs">{r.value}</td><td class="py-1.5">{r.status}</td></tr>{/each}</tbody></table></div>
      <button class="btn mt-3" disabled={busy} onclick={() => go("/api/documents/email/domain/verify", {}, t("Checked."))}>{t("Check the records now")}</button>
    {:else}<form class="mt-3 flex flex-wrap gap-2" onsubmit={(e) => { e.preventDefault(); go("/api/documents/email/domain", { domain: domain.trim() }, t("Added. Add the records below at your DNS host."));  }}><input class="field !w-72 !py-1.5" placeholder="yourcompany.com" bind:value={domain} aria-label={t("Your domain")} /><button class="btn primary" disabled={busy || !domain.trim()}>{t("Add domain")}</button></form>{/if}</section>
  <section class="rounded-xl border border-line p-5"><h2 class="font-semibold">{t("Or send through your own mail server")}</h2><p class="mt-1 text-sm text-mute">{t("The password is stored sealed and never shown again.")}</p>
    <form class="mt-3 flex flex-wrap gap-2" onsubmit={(e) => { e.preventDefault(); go("/api/documents/email/smtp-password", { password: pw }, t("Password saved.")); pw = ""; }}><input class="field !w-72 !py-1.5" type="password" autocomplete="new-password" placeholder={st.smtp?.passwordSet ? t("A password is set — type to replace") : t("SMTP password")} bind:value={pw} aria-label={t("SMTP password")} /><button class="btn" disabled={busy || !pw}>{t("Save password")}</button></form></section>
  <section class="rounded-xl border border-line p-5"><h2 class="font-semibold">{t("Send yourself a test")}</h2>
    <form class="mt-3 flex flex-wrap gap-2" onsubmit={(e) => { e.preventDefault(); go("/api/documents/email/test", { to: to.trim() }, t("A test email is on its way.")); }}><input class="field !w-72 !py-1.5" type="email" placeholder="you@example.com" bind:value={to} aria-label={t("Send the test to")} /><button class="btn" disabled={busy || !to.trim()}>{t("Send test")}</button></form></section>
  {#if note}<p class="text-sm" role="status">{note}</p>{/if}
</div>{/if}
